  <!-- Technical API Reference -->
  <section class="section container" id="api" aria-labelledby="api-title">
    <div class="section-header">
      <div>
        <h2 class="section-title" id="api-title">API Reference</h2>
        <p class="section-desc">Methods and configuration options exposed by the engine.</p>
      </div>
      <span class="section-meta">TypeScript Definitions</span>
    </div>

    <div class="api-table-wrapper">
      <table class="api-table">
        <thead>
          <tr>
            <th>Property / Method</th>
            <th>Type</th>
            <th>Default</th>
            <th>Description</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td><code>createInkTransition(opts?)</code></td>
            <td><code>(options?: Options) =&gt; InkTransition</code></td>
            <td><code>-</code></td>
            <td>Initializes and mounts WebGL2 engine with fallback. Options: <code>toggleButton</code>, <code>webgl</code>, <code>preset</code>, <code>captureMode</code>, <code>captureOnToggle</code>, <code>onToggle</code>.</td>
          </tr>
          <tr>
            <td><code>ink.toggle(point?, seed?)</code></td>
            <td><code>(point?: Point, seed?: Seed) =&gt; void</code></td>
            <td><code>toggleCenter()</code></td>
            <td>Triggers organic radial expansion from viewport coordinates. Locked while transitioning to prevent conflicting animations.</td>
          </tr>
          <tr>
            <td><code>ink.isAnimating</code></td>
            <td><code>boolean</code></td>
            <td><code>false</code></td>
            <td>True while the transition wave or fade-out overlay is actively animating.</td>
          </tr>
          <tr>
            <td><code>ink.activePreset</code></td>
            <td><code>PresetName</code></td>
            <td><code>'ink'</code></td>
            <td>Returns the active shader preset (<code>'ink' | 'watercolor' | 'smoke' | 'ember' | 'ripple'</code>).</td>
          </tr>
          <tr>
            <td><code>ink.setPreset(name)</code></td>
            <td><code>(name: PresetName) =&gt; void</code></td>
            <td><code>'ink'</code></td>
            <td>Switches live shader parameters (duration, tendril, noiseScale, softness, drift).</td>
          </tr>
          <tr>
            <td><code>ink.setCaptureMode(mode)</code></td>
            <td><code>(mode: 'viewport' | 'full') =&gt; void</code></td>
            <td><code>'viewport'</code></td>
            <td>Configures snapshot strategy: fast viewport mode (~30ms) or full document.</td>
          </tr>
          <tr>
            <td><code>ink.replay()</code></td>
            <td><code>() =&gt; boolean</code></td>
            <td><code>-</code></td>
            <td>Re-runs the previous click using identical seed, preset, and origin coordinates.</td>
          </tr>
        </tbody>
      </table>
    </div>
  </section>
